                                            pd2_ab, pd2_bb, pd3_aaa, pd3_aab, pd3_abb, pd3_bbb, &
                                            pd4_aaaa, pd4_aaab, pd4_aabb, pd4_abbb, pd4_bbbb, &
                                            sg_a, sg_b)
      !> Displacement r - r_a
      real(wp), intent(in) :: d_a(3)
