      real(wp), intent(inout) :: pd2_aa(3, 3)
      !> d^2 K / d(d_a)^1 d(d_b)^1 accumulator (no index symmetry)
      real(wp), intent(inout) :: pd2_ab(3, 3)
      !> d^2 K / d(d_a)^0 d(d_b)^2 accumulator (symmetric in the last 2 indices)
      real(wp), intent(inout) :: pd2_bb(3, 3)
      !> d^3 K / d(d_a)^3 d(d_b)^0 accumulator (symmetric in the first 3 indices)
      real(wp), intent(inout) :: pd3_aaa(3, 3, 3)
      !> d^3 K / d(d_a)^2 d(d_b)^1 accumulator (symmetric in the first 2 indices)
      real(wp), intent(inout) :: pd3_aab(3, 3, 3)
      !> d^3 K / d(d_a)^1 d(d_b)^2 accumulator (symmetric in the last 2 indices)
      real(wp), intent(inout) :: pd3_abb(3, 3, 3)
      !> d^3 K / d(d_a)^0 d(d_b)^3 accumulator (symmetric in the last 3 indices)
      real(wp), intent(inout) :: pd3_bbb(3, 3, 3)
      !> d^4 K / d(d_a)^4 d(d_b)^0 accumulator (symmetric in the first 4 indices)
      real(wp), intent(inout) :: pd4_aaaa(3, 3, 3, 3)
      !> d^4 K / d(d_a)^3 d(d_b)^1 accumulator (symmetric in the first 3 indices)
      real(wp), intent(inout) :: pd4_aaab(3, 3, 3, 3)
      !> d^4 K / d(d_a)^2 d(d_b)^2 accumulator (symmetric within each index group)
      real(wp), intent(inout) :: pd4_aabb(3, 3, 3, 3)
      !> d^4 K / d(d_a)^1 d(d_b)^3 accumulator (symmetric in the last 3 indices)
      real(wp), intent(inout) :: pd4_abbb(3, 3, 3, 3)
      !> d^4 K / d(d_a)^0 d(d_b)^4 accumulator (symmetric in the last 4 indices)
      real(wp), intent(inout) :: pd4_bbbb(3, 3, 3, 3)
      !> Reduced distance sigma = ||d_a||/R_a - 1 of center a
      real(wp), intent(in) :: sg_a
      !> Reduced distance sigma = ||d_b||/R_b - 1 of center b
      real(wp), intent(in) :: sg_b

      !> Fade: band end, reciprocal width, raw and clamped s, t, ds/dsigma
      real(wp) :: band_end, inv_delta, sr, fs, ft, dsdd
      !> d^j P_n/ds^j of the reduced smoothstep polynomial, w = s**(n+1) P_n(s)
      real(wp) :: fp0, fp1, fp2, fp3, fp4
      !> Powers s**k of the fade variable
      real(wp) :: fsp1, fsp2, fsp3, fsp4, fsp5
      !> Unfaded factor exp(a2 (sigma_a + sigma_b)), on g_a
      real(wp) :: fu
      !> Faded radial factor and its sigma derivatives d^j/dsigma^j, g = w exp(a2 sigma) per center, g_b without its exp (carried by g_a)
      real(wp) :: g_a(0:4), g_b(0:4)
      !> Common subexpressions of the radial jets
      real(wp) :: fj0, fj1, fj2, fj3, fj4, fj5, fj6, fj7, fj8

      if (.not. fade_width > 0.0_wp) error stop &
         "cfc_pair_term_eval: fade_width must be positive"
      band_end = fade_start + fade_width
      ! Beyond the band of a center: w = 0, nothing to add
      if (sg_a >= band_end .or. sg_b >= band_end) return
      inv_delta = 1.0_wp/fade_width
      select case (max_deriv)
      case (0)
         block
            sr = (band_end - (sg_a))*inv_delta
            fs = min(max(sr, 0.0_wp), 1.0_wp)
            ft = min(max((sg_a - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
            dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
            fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
            fsp1 = fs
            fsp2 = fsp1*fs
            fsp3 = fsp2*fs
            fsp4 = fsp3*fs
            fsp5 = fsp4*fs
            fu = exp(a2*(sg_a + sg_b))
            g_a(0) = fp0*fsp5*fu
            sr = (band_end - (sg_b))*inv_delta
            fs = min(max(sr, 0.0_wp), 1.0_wp)
            ft = min(max((sg_b - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
            dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
            fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
            fsp1 = fs
            fsp2 = fsp1*fs
            fsp3 = fsp2*fs
            fsp4 = fsp3*fs
            fsp5 = fsp4*fs
            g_b(0) = fp0*fsp5
            pd0 = &
               pd0 + (c_par*g_a(0)*g_b(0)*((1.0_wp - (d_a(1)*d_b(1) + d_a(2)*d_b(2) + &
               d_a(3)*d_b(3))/(R_a*R_b))*(1.0_wp - (d_a(1)*d_b(1) + d_a(2)*d_b(2) + &
               d_a(3)*d_b(3))/(R_a*R_b))*(1.0_wp - (d_a(1)*d_b(1) + d_a(2)*d_b(2) + &
               d_a(3)*d_b(3))/(R_a*R_b))*(1.0_wp - (d_a(1)*d_b(1) + d_a(2)*d_b(2) + &
               d_a(3)*d_b(3))/(R_a*R_b))))
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12

            sr = (band_end - (sg_a))*inv_delta
            fs = min(max(sr, 0.0_wp), 1.0_wp)
            ft = min(max((sg_a - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
            dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
            fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
            fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
            fsp1 = fs
            fsp2 = fsp1*fs
            fsp3 = fsp2*fs
            fsp4 = fsp3*fs
            fsp5 = fsp4*fs
            fu = exp(a2*(sg_a + sg_b))
            fj0 = fp0*fsp5
            g_a(0) = fj0*fu
            g_a(1) = fu*(a2*fj0 + dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5))
            sr = (band_end - (sg_b))*inv_delta
            fs = min(max(sr, 0.0_wp), 1.0_wp)
            ft = min(max((sg_b - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
            dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
            fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
            fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
            fsp1 = fs
            fsp2 = fsp1*fs
            fsp3 = fsp2*fs
            fsp4 = fsp3*fs
            fsp5 = fsp4*fs
            fj0 = fp0*fsp5
            g_b(0) = fj0
            g_b(1) = a2*fj0 + dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5)
            x0 = 1.0_wp/R_a
            x1 = 1.0_wp/R_b
            x2 = x0*x1
            x3 = -x2*(d_a(1)*d_b(1) + d_a(2)*d_b(2) + d_a(3)*d_b(3)) + 1.0_wp
            x4 = (x3*x3*x3*x3)
            x5 = c_par*g_b(0)*x4
            x6 = c_par*g_a(0)
            x7 = d_b(1)*x6
            x8 = 4.0_wp*g_b(0)*x2*(x3*x3*x3)
            x9 = g_a(1)*x0*x5/sqrt(((d_a(1)*d_a(1)) + (d_a(2)*d_a(2)) + (d_a(3)*d_a(3))))
            x10 = x6*x8
            x11 = g_b(1)*x1*x4/sqrt(((d_b(1)*d_b(1)) + (d_b(2)*d_b(2)) + (d_b(3)*d_b(3))))
            x12 = x11*x6
            pd0 = pd0 + (g_a(0)*x5)
            pd1_a(1) = pd1_a(1) + (d_a(1)*x9 - x7*x8)
            pd1_a(2) = pd1_a(2) + (d_a(2)*x9 - d_b(2)*x10)
            pd1_a(3) = pd1_a(3) + (d_a(3)*x9 - d_b(3)*x10)
            pd1_b(1) = pd1_b(1) + (-d_a(1)*x10 + x11*x7)
            pd1_b(2) = pd1_b(2) + (-d_a(2)*x10 + d_b(2)*x12)
            pd1_b(3) = pd1_b(3) + (-d_a(3)*x10 + d_b(3)*x12)
         end block
      case (2)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
            real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, x42, x43, x44, x45, x46
            real(wp) :: x47, x48, x49, x50, x51, x52, x53, x54, x55, x56, x57, x58, x59, x60, x61
            real(wp) :: x62, x63, x64, x65, x66, x67, x68, x69, x70, x71, x72, x73, x74, x75, x76
            real(wp) :: x77, x78, x79, x80, x81, t_pd2_aa_01, t_pd2_aa_02, t_pd2_aa_12, t_pd2_bb_01
            real(wp) :: t_pd2_bb_02, t_pd2_bb_12

            sr = (band_end - (sg_a))*inv_delta
            fs = min(max(sr, 0.0_wp), 1.0_wp)
            ft = min(max((sg_a - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
            dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
            fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
            fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
            fp2 = ft*(840.0_wp*ft + 210.0_wp) + 30.0_wp
            fsp1 = fs
            fsp2 = fsp1*fs
            fsp3 = fsp2*fs
            fsp4 = fsp3*fs
            fsp5 = fsp4*fs
            fu = exp(a2*(sg_a + sg_b))
            fj0 = fp0*fsp5
            fj1 = dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5)
            g_a(0) = fj0*fu
            g_a(1) = fu*(a2*fj0 + fj1)
            g_a(2) = &
               fu*((a2*a2)*fj0 + 2.0_wp*a2*fj1 + (dsdd*dsdd)*fsp3*(20.0_wp*fp0 + 10.0_wp*fp1*fs + &
               fp2*fsp2))
            sr = (band_end - (sg_b))*inv_delta
            fs = min(max(sr, 0.0_wp), 1.0_wp)
            ft = min(max((sg_b - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
            dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
            fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
            fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
            fp2 = ft*(840.0_wp*ft + 210.0_wp) + 30.0_wp
            fsp1 = fs
            fsp2 = fsp1*fs
            fsp3 = fsp2*fs
            fsp4 = fsp3*fs
            fsp5 = fsp4*fs
            fj0 = fp0*fsp5
            fj1 = dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5)
            g_b(0) = fj0
            g_b(1) = a2*fj0 + fj1
            g_b(2) = &
               (a2*a2)*fj0 + 2.0_wp*a2*fj1 + (dsdd*dsdd)*fsp3*(20.0_wp*fp0 + 10.0_wp*fp1*fs + &
               fp2*fsp2)
            x0 = c_par*g_a(0)
            x1 = d_a(1)*d_b(1)
            x2 = d_a(2)*d_b(2)
            x3 = d_a(3)*d_b(3)
            x4 = 1.0_wp/R_a
            x5 = 1.0_wp/R_b
            x6 = x4*x5
            x7 = -x6*(x1 + x2 + x3) + 1.0_wp
            x8 = (x7*x7*x7*x7)
            x9 = g_b(0)*x8
            x10 = g_b(0)*x0
            x11 = (x7*x7*x7)
            x12 = 4.0_wp*x11
            x13 = x10*x12*x6
            x14 = (d_a(1)*d_a(1))
            x15 = (d_a(2)*d_a(2))
            x16 = (d_a(3)*d_a(3))
            x17 = x14 + x15 + x16
            x18 = 1.0_wp/sqrt(x17)
            x19 = g_a(1)*x18
            x20 = c_par*x9
            x21 = x20*x4
            x22 = x19*x21
            x23 = (d_b(1)*d_b(1))
            x24 = (d_b(2)*d_b(2))
            x25 = (d_b(3)*d_b(3))
            x26 = x23 + x24 + x25
            x27 = 1.0_wp/sqrt(x26)
            x28 = g_b(1)*x27
            x29 = x0*x8
            x30 = x29*x5
            x31 = x28*x30
            x32 = 1.0_wp/(R_b*R_b)
            x33 = x23*x32
            x34 = 1.0_wp/(R_a*R_a)
            x35 = (x7*x7)
            x36 = 12.0_wp*x10*x35
            x37 = x34*x36
            x38 = x14*x34
            x39 = 1.0_wp/x17
            x40 = g_a(2)*x20*x39
            x41 = g_a(1)*x21/(x17*sqrt(x17))
            x42 = 8.0_wp*x11
            x43 = x1*x42
            x44 = c_par*x19
            x45 = g_b(0)*x44*x5
            x46 = x34*x45
            x47 = d_a(1)*d_a(2)
            x48 = x12*x45
            x49 = x34*x48
            x50 = d_a(1)*x49
            x51 = d_b(1)*x49
            x52 = d_a(1)*d_a(3)
            x53 = x32*x37
            x54 = x34*x40
            x55 = x42*x46
            x56 = d_a(2)*d_a(3)
            x57 = d_a(2)*d_b(3)
            x58 = d_a(3)*d_b(2)
            x59 = x0*x28*x4
            x60 = x12*x59
            x61 = d_b(1)*x53
            x62 = x28*x44*x6*x8
            x63 = d_a(1)*x62
            x64 = d_b(1)*d_b(2)
            x65 = x32*x60
            x66 = -x47*x49 - x64*x65
            x67 = d_b(1)*d_b(3)
            x68 = -x49*x52 - x65*x67
            x69 = d_b(2)*x53
            x70 = d_b(1)*x62
            x71 = d_b(2)*d_b(3)
            x72 = -x49*x56 - x65*x71
            x73 = d_b(3)*x53
            x74 = 1.0_wp/x26
            x75 = g_b(2)*x29*x74
            x76 = g_b(1)*x30/(x26*sqrt(x26))
            x77 = x32*x59
            x78 = d_a(1)*x65
            x79 = d_b(1)*x65
            x80 = x32*x75
            x81 = x42*x77
            pd0 = pd0 + (x0*x9)
            pd1_a(1) = pd1_a(1) + (d_a(1)*x22 - d_b(1)*x13)
            pd1_a(2) = pd1_a(2) + (d_a(2)*x22 - d_b(2)*x13)
            pd1_a(3) = pd1_a(3) + (d_a(3)*x22 - d_b(3)*x13)
            pd1_b(1) = pd1_b(1) + (-d_a(1)*x13 + d_b(1)*x31)
            pd1_b(2) = pd1_b(2) + (-d_a(2)*x13 + d_b(2)*x31)
            pd1_b(3) = pd1_b(3) + (-d_a(3)*x13 + d_b(3)*x31)
            pd2_aa(1, 1) = pd2_aa(1, 1) + (-x14*x41 + x22 + x33*x37 + x38*x40 - x43*x46)
            t_pd2_aa_01 = &
               c_par*d_a(1)*d_a(2)*g_a(2)*g_b(0)*x34*x39*x8 + &
               12.0_wp*c_par*d_b(1)*d_b(2)*g_a(0)*g_b(0)*x32*x34*x35 - d_a(2)*x51 - d_b(2)*x50 - &
               x41*x47
            pd2_aa(1, 2) = pd2_aa(1, 2) + t_pd2_aa_01
            pd2_aa(2, 1) = pd2_aa(2, 1) + t_pd2_aa_01
            t_pd2_aa_02 = &
               c_par*d_a(1)*d_a(3)*g_a(2)*g_b(0)*x34*x39*x8 + &
               12.0_wp*c_par*d_b(1)*d_b(3)*g_a(0)*g_b(0)*x32*x34*x35 - d_a(3)*x51 - d_b(3)*x50 - &
               x41*x52
            pd2_aa(1, 3) = pd2_aa(1, 3) + t_pd2_aa_02
            pd2_aa(3, 1) = pd2_aa(3, 1) + t_pd2_aa_02
            pd2_aa(2, 2) = pd2_aa(2, 2) + (-x15*x41 + x15*x54 - x2*x55 + x22 + x24*x53)
            t_pd2_aa_12 = &
               c_par*d_a(2)*d_a(3)*g_a(2)*g_b(0)*x34*x39*x8 + &
               12.0_wp*c_par*d_b(2)*d_b(3)*g_a(0)*g_b(0)*x32*x34*x35 - x41*x56 - x49*x57 - x49*x58
            pd2_aa(2, 3) = pd2_aa(2, 3) + t_pd2_aa_12
            pd2_aa(3, 2) = pd2_aa(3, 2) + t_pd2_aa_12
            pd2_aa(3, 3) = pd2_aa(3, 3) + (-x16*x41 + x16*x54 + x22 + x25*x53 - x3*x55)
            pd2_ab(1, 1) = &
               pd2_ab(1, 1) + (12.0_wp*c_par*d_a(1)*d_b(1)*g_a(0)*g_b(0)*x32*x34*x35 + &
               c_par*d_a(1)*d_b(1)*g_a(1)*g_b(1)*x18*x27*x4*x5*x8 - x13 - x33*x60 - x38*x48)
            pd2_ab(1, 2) = pd2_ab(1, 2) + (d_a(2)*x61 + d_b(2)*x63 + x66)
            pd2_ab(1, 3) = pd2_ab(1, 3) + (d_a(3)*x61 + d_b(3)*x63 + x68)
            pd2_ab(2, 1) = pd2_ab(2, 1) + (d_a(1)*x69 + d_a(2)*x70 + x66)
            pd2_ab(2, 2) = &
               pd2_ab(2, 2) + (12.0_wp*c_par*d_a(2)*d_b(2)*g_a(0)*g_b(0)*x32*x34*x35 + &
               c_par*d_a(2)*d_b(2)*g_a(1)*g_b(1)*x18*x27*x4*x5*x8 - x13 - x15*x49 - x24*x65)
            pd2_ab(2, 3) = pd2_ab(2, 3) + (d_a(3)*x69 + x57*x62 + x72)
            pd2_ab(3, 1) = pd2_ab(3, 1) + (d_a(1)*x73 + d_a(3)*x70 + x68)
            pd2_ab(3, 2) = pd2_ab(3, 2) + (d_a(2)*x73 + x58*x62 + x72)
            pd2_ab(3, 3) = &
               pd2_ab(3, 3) + (12.0_wp*c_par*d_a(3)*d_b(3)*g_a(0)*g_b(0)*x32*x34*x35 + &
               c_par*d_a(3)*d_b(3)*g_a(1)*g_b(1)*x18*x27*x4*x5*x8 - x13 - x16*x49 - x25*x65)
            pd2_bb(1, 1) = pd2_bb(1, 1) + (-x23*x76 + x31 + x32*x36*x38 + x33*x75 - x43*x77)
            t_pd2_bb_01 = &
               12.0_wp*c_par*d_a(1)*d_a(2)*g_a(0)*g_b(0)*x32*x34*x35 + &
               c_par*d_b(1)*d_b(2)*g_a(0)*g_b(2)*x32*x74*x8 - d_a(2)*x79 - d_b(2)*x78 - x64*x76
            pd2_bb(1, 2) = pd2_bb(1, 2) + t_pd2_bb_01
            pd2_bb(2, 1) = pd2_bb(2, 1) + t_pd2_bb_01
            t_pd2_bb_02 = &
               12.0_wp*c_par*d_a(1)*d_a(3)*g_a(0)*g_b(0)*x32*x34*x35 + &
               c_par*d_b(1)*d_b(3)*g_a(0)*g_b(2)*x32*x74*x8 - d_a(3)*x79 - d_b(3)*x78 - x67*x76
            pd2_bb(1, 3) = pd2_bb(1, 3) + t_pd2_bb_02
            pd2_bb(3, 1) = pd2_bb(3, 1) + t_pd2_bb_02
            pd2_bb(2, 2) = pd2_bb(2, 2) + (x15*x53 - x2*x81 - x24*x76 + x24*x80 + x31)
            t_pd2_bb_12 = &
               12.0_wp*c_par*d_a(2)*d_a(3)*g_a(0)*g_b(0)*x32*x34*x35 + &
               c_par*d_b(2)*d_b(3)*g_a(0)*g_b(2)*x32*x74*x8 - x57*x65 - x58*x65 - x71*x76
            pd2_bb(2, 3) = pd2_bb(2, 3) + t_pd2_bb_12
            pd2_bb(3, 2) = pd2_bb(3, 2) + t_pd2_bb_12
            pd2_bb(3, 3) = pd2_bb(3, 3) + (x16*x53 - x25*x76 + x25*x80 - x3*x81 + x31)
         end block
      case (3)
         block
